const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;

    const lastPos = new Int32Array(100005);
    lastPos.fill(-1);

    let maxLen = 0;
    let left = 0;

    for (let right = 0; right < N; right++) {
        const val = readInt();
        if (lastPos[val] >= left) {
            left = lastPos[val] + 1;
        }
        lastPos[val] = right;
        const currentLen = right - left + 1;
        if (currentLen > maxLen) {
            maxLen = currentLen;
        }
    }

    console.log(maxLen);
}

solve();
